using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class GradeCompetencyTests
{
 class User(int emp=1,bool hr=true):ICurrentUser{public string Email=>"framework@example.local";public int? EmployeeId=>emp;public int UserId=>emp;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static PerfService S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,u,new AccessScope(d,u),c,a,new NotificationService(d,u,c));}
 static async Task<int> Appraisal(AppDbContext d){var cycle=new PerfCycle{Name="Fictional framework test",Start=new(2026,1,1),End=new(2027,12,31),Status=CycleStatus.Open};d.Add(cycle);await d.SaveAsync();var a=new PerfAppraisal{CycleId=cycle.Id,EmployeeId=6};d.Add(a);await d.SaveAsync();return a.Id;}
 [Fact]public async Task GradeMismatchBlocksApplicationWithoutAnyGoals(){await using var d=await Db();var id=await Appraisal(d);var grade=(await d.Set<Employee>().FindAsync(6))!.JobTitle!.Grade;await S(d).AddTemplateAsync("Fictional wrong grade",grade+1);var t=await d.Set<CompetencyTemplate>().SingleAsync(x=>x.Name=="Fictional wrong grade");await S(d).AddCompetencyAsync(t.Id,"Competency","Observable expected behaviour",100);await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyTemplateAsync(id,t.Id));Assert.Empty(await d.Set<PerfGoal>().Where(x=>x.AppraisalId==id).ToListAsync());}
 [Fact]public async Task CompleteGradeFrameworkCapturesImmutableContentAndPreventsDoubleApply(){await using var d=await Db();var id=await Appraisal(d);var grade=(await d.Set<Employee>().FindAsync(6))!.JobTitle!.Grade;await S(d).AddTemplateAsync("Fictional grade framework",grade);var t=await d.Set<CompetencyTemplate>().SingleAsync(x=>x.Name=="Fictional grade framework");await S(d).AddCompetencyAsync(t.Id,"Safe practice","Uses fictional data only",100);await S(d).ApplyTemplateAsync(id,t.Id);var evidence=(await S(d).CompetencyEvidenceAsync(id))!;Assert.Contains("fictional data",evidence.Content);Assert.Equal(64,evidence.Sha256.Length);Assert.Single(await d.Set<PerfGoal>().Where(x=>x.AppraisalId==id).ToListAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyTemplateAsync(id,t.Id));evidence=(await d.Set<CompetencyApplication>().SingleAsync(x=>x.AppraisalId==id));evidence.Content="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task UnrestrictedLegacyTemplateWorksAndSourceChangesDoNotRewriteEvidence(){await using var d=await Db();var id=await Appraisal(d);await S(d).AddTemplateAsync("Fictional unrestricted");var t=await d.Set<CompetencyTemplate>().SingleAsync(x=>x.Name=="Fictional unrestricted");await S(d).AddCompetencyAsync(t.Id,"Original","Observable behaviour",100);await S(d).ApplyTemplateAsync(id,t.Id);var ev=(await S(d).CompetencyEvidenceAsync(id))!;var original=ev.Content;var item=await d.Set<CompetencyItem>().SingleAsync(x=>x.TemplateId==t.Id);item.Title="Changed source";await d.SaveAsync();Assert.Equal(original,(await S(d).CompetencyEvidenceAsync(id))!.Content);Assert.Equal("Original",(await d.Set<PerfGoal>().SingleAsync(x=>x.AppraisalId==id)).Title);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7,false)).CompetencyEvidenceAsync(id));}
 [Fact]public async Task InputsWeightsAndPermissionsStayExplicit(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).AddTemplateAsync("No"));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddTemplateAsync("Bad grade",-1));await S(d).AddTemplateAsync("Fictional incomplete");var t=await d.Set<CompetencyTemplate>().SingleAsync(x=>x.Name=="Fictional incomplete");await Assert.ThrowsAsync<DomainException>(()=>S(d).AddCompetencyAsync(t.Id,"Title","",50));await S(d).AddCompetencyAsync(t.Id,"Title","Observed expectation",60);await Assert.ThrowsAsync<DomainException>(()=>S(d).AddCompetencyAsync(t.Id,"Title2","Observed expectation",50));var id=await Appraisal(d);await Assert.ThrowsAsync<DomainException>(()=>S(d).ApplyTemplateAsync(id,t.Id));Assert.Empty(await d.Set<CompetencyApplication>().ToListAsync());}
}
